"""Actual speaker/editor callbacks, inheritance, playback and bounded UI scrolling."""
from test_bufftap import test
BASE="local B=BuffTap; B:Options(); "
def run(name,code):test(name,BASE+code)
run('Right-click personal speaker opens scoped editor without muting',"local r=B.options.buffRows[1]; r.sound.scripts.OnClick(r.sound,'RightButton'); local p=B.buffSoundEditor; assert(p.shown and p.context=='personal' and p.key==r.def.key and B:BuffAlertEnabled('personal',r.def)); assert(p.title.text:find('Personal')); assert(p.rows[1].select.text:find('Use default:'))")
run('Editor selection saves custom sound without unmuting or previewing',"B:SetBuffAlertEnabled('personal','motw',false); B:OpenBuffSoundEditor('personal','motw'); local p=B.buffSoundEditor; local heard=0; PlaySoundFile=function() heard=heard+1; return true end; for _,r in ipairs(p.rows) do if r.select.soundKey=='moonlitbells' then r.select.scripts.OnClick(r.select); break end end; assert(B:BuffAlertSound('personal','motw')=='moonlitbells' and not B:BuffAlertEnabled('personal','motw') and heard==0)")
run('Row preview uses clicked sound without changing selection even muted',"B:SetBuffAlertEnabled('personal','motw',false); B:SetBuffAlertSound('personal','motw','harp'); B:OpenBuffSoundEditor('personal','motw'); local p=B.buffSoundEditor; local path; PlaySoundFile=function(file) path=file; return true end; B.db.sound=false; for _,r in ipairs(p.rows) do if r.preview.soundKey=='holylight' then r.preview.scripts.OnClick(r.preview); break end end; assert(path:find('BuffTapHolyLight.ogg',1,true)); assert(B:BuffAlertSound('personal','motw')=='harp' and not B:BuffAlertEnabled('personal','motw'))")
run('Use default clears only custom sound and follows later default changes',"B:SetBuffAlertEnabled('personal','motw',false); B:SetBuffAlertSound('personal','motw','harp'); B:OpenBuffSoundEditor('personal','motw'); B.buffSoundEditor.rows[1].select.scripts.OnClick(B.buffSoundEditor.rows[1].select); assert(not B:BuffAlertSound('personal','motw') and not B:BuffAlertEnabled('personal','motw')); B.db.reminderSound='moonlitbells'; B:OpenBuffSoundEditor('personal','motw'); assert(B.buffSoundEditor.rows[1].select.text:find('Moonlit bells',1,true))")
run('Custom automatic playback is isolated by personal Party Raid and family',"B:SetBuffAlertSound('personal','motw','holylight'); B:SetBuffAlertSound('party','motw','elvenharp'); B:SetBuffAlertSound('raid','gotw','moonlitbells'); B.db.sound=true; local path; PlaySoundFile=function(file) path=file; return true end; for _,entry in ipairs({{'solo','player',false,'BuffTapHolyLight.ogg'},{'party','party1',false,'BuffTapElvenHarp.ogg'},{'raid','raid1',true,'BuffTapMoonlitBells.ogg'}}) do B.situationCurrent=entry[1]; B.action={key=entry[3] and 'gotw' or 'motw',target=entry[2],groupCast=entry[3]}; B.lastAlertSound=nil; assert(B:PlayAlert('reminder')); assert(path:find(entry[4],1,true)) end")
run('Custom sound never bypasses category mute or existing pause checks',"B:SetBuffAlertSound('personal','motw','holylight'); B.action={key='motw',target='player'}; local heard=0; PlaySoundFile=function() heard=heard+1; return true end; B.db.sound=false; assert(not B:PlayAlert('reminder')); B.db.sound=true; B:SetBuffAlertEnabled('personal','motw',false); assert(not B:PlayAlert('reminder')); B:SetBuffAlertEnabled('personal','motw',true); B.db.pauseResting=true; IsResting=function() return true end; assert(not B:PlayAlert('reminder') and heard==0)")
run('Custom sound survives export import and mute toggles',"B:SetBuffAlertSound('personal','motw','moonlitbells'); local text=B:ExportSettings(); B:SetBuffAlertSound('personal','motw',nil); assert(B:ImportSettings(text)); B:SetBuffAlertEnabled('personal','motw',false); B:SetBuffAlertEnabled('personal','motw',true); assert(B:BuffAlertSound('personal','motw')=='moonlitbells')")
run('Invalid contexts sounds and combat edits fail without mutation',"assert(not B:SetBuffAlertSound('unknown','motw','harp')); assert(not B:SetBuffAlertSound('personal','motw','bogus')); combat=true; assert(not B:SetBuffAlertSound('personal','motw','harp')); assert(not B:OpenBuffSoundEditor('personal','motw'))")
run('Party and Raid speakers open correct custom sound scope',"local f=B.options; for _,context in ipairs({'Party','Raid'}) do f.groupContext=context; B:Options(); local r=f.assignRows[1]; r.sound.scripts.OnClick(r.sound,'RightButton'); assert(B.buffSoundEditor.context==context:lower() and B.buffSoundEditor.key==r.def.key) end")
run('Paladin speaker opens editor for unlearned blessing',"playerClass='PALADIN'; B:InitDB(); B.options=nil; B:Options(); B.options.blessingContext='Raid'; B:ToggleBlessingSounds(); local c=B.options.blessingSounds.checks.bok; c.scripts.OnClick(c,'RightButton'); assert(B.buffSoundEditor.shown and B.buffSoundEditor.context=='raid' and B.buffSoundEditor.key=='bok')")
run('Search matches names and default remains available',"B:OpenBuffSoundEditor('personal','motw'); local p=B.buffSoundEditor; p.search:SetText('moonlit'); p.search.scripts.OnTextChanged(); assert(p.rows[1].select.soundKey==false and p.rows[2].select.soundKey=='moonlitbells' and not p.rows[3].select.shown); p.search:SetText('not a sound'); p.search.scripts.OnTextChanged(); assert(p.empty.shown)")
run('Editor closes on combat and on Escape',"B:OpenBuffSoundEditor('personal','motw'); local p=B.buffSoundEditor; p.scripts.OnKeyDown(p,'ESCAPE'); assert(not p.shown); B:OpenBuffSoundEditor('personal','motw'); p.scripts.OnEvent(p,'PLAYER_REGEN_DISABLED'); assert(not p.shown)")
SCROLL=r"""
local T=B.OptionsTheme; local f=CreateFrame('ScrollFrame'); f.position=0; f.optionsScrollRange=500
f.GetVerticalScroll=function(self) return self.position end; f.SetVerticalScroll=function(self,v) self.position=v end
"""
run('Smooth wheel uses small bounded steps and stops when finished',SCROLL+"T.SmoothWheel(f,20); f.scripts.OnMouseWheel(f,-1); assert(f.optionsScrollTarget==20 and f.position==0); local a=f.optionsScrollAnimator; for i=1,80 do if a.scripts.OnUpdate then a.scripts.OnUpdate(a,.016) end end; assert(f.position==20 and not a.scripts.OnUpdate); f.scripts.OnMouseWheel(f,100); assert(f.optionsScrollTarget==0 or f.position==0)")
run('Reduce animation makes scrolling immediate without idle update',SCROLL+"B.db.optionsReduceMotion=true; T.SmoothWheel(f,20); f.scripts.OnMouseWheel(f,-2); assert(f.position==40 and not f.optionsScrollAnimator.scripts.OnUpdate)")
run('Opening dropdown jumps directly to selected sound and resets old search',"local c=B.options.reminderSoundButton; B.db.reminderSound='lullabyping'; B:Options(); local p=c.menu; local y; p.scroll.SetVerticalScroll=function(_,v) y=v end; p.scroll.GetVerticalScroll=function() return y or 0 end; p.search:SetText('no match'); c.scripts.OnClick(); assert(p.search.text=='' and y>0 and not p.scroll.optionsScrollAnimator.scripts.OnUpdate)")
run('Opening editor centres selected row and does not autoplay',"B:SetBuffAlertSound('personal','motw','lullabyping'); local heard=0; PlaySoundFile=function() heard=heard+1; return true end; B:OpenBuffSoundEditor('personal','motw'); local p=B.buffSoundEditor; local y; p.scroll.SetVerticalScroll=function(_,v) y=v end; p.scroll.GetVerticalScroll=function() return y or 0 end; B:RenderBuffSoundEditor(true); assert(y>0 and heard==0)")
run('Speaker tooltip names override and explains right click',"B:SetBuffAlertSound('personal','motw','holylight'); local t=B:BuffAlertTooltip('personal','motw'); assert(t:find('Holy light',1,true) and t:find('Right-click',1,true))")

run('Unavailable per-buff SharedMedia choice stays visible and saved',"B.db.buffAlerts.personal.motw={enabled=true,sound='lsm:Missing pack sound'}; B:NormalizeAlerts(); B:OpenBuffSoundEditor('personal','motw'); local found; for _,r in ipairs(B.buffSoundEditor.rows) do if r.select.soundKey=='lsm:Missing pack sound' then found=r.select.text end end; assert(found and found:find('unavailable') and B:BuffAlertSound('personal','motw')=='lsm:Missing pack sound')")
run('SharedMedia custom override uses registered file and respects mute',"LibStub=function() return {HashTable=function() return {Custom='path/custom.ogg'} end} end; assert(B:SetBuffAlertSound('personal','motw','lsm:Custom')); B.action={key='motw',target='player'}; B.db.sound=true; B.lastAlertSound=nil; local file; PlaySoundFile=function(path) file=path; return true end; assert(B:PlayAlert('reminder') and file=='path/custom.ogg'); B:SetBuffAlertEnabled('personal','motw',false); assert(not B:PlayAlert('reminder'))")
